class student_Type {
    /* Function Objective: Compute the GPAX of one student
       Input parameters : f_point_total (float) weighted grade points, f_credit_total (float) registered credits
       Function description: Divide the weighted grade points by the registered credits, capped at the maximum GPAX
       Return Value : float GPAX value
       Created By : Programmer A
       Create Date: 2026-09-28
       Revised By:
       Revised Date:
    */
    static float f_Calculate_Gpax(float f_point_total, float f_credit_total) {
        final float maxGpax = 4.0f;
        float f_gpax = 0.0f;
        // check that credits were registered
        if (f_credit_total > 0) {
            f_gpax = f_point_total / f_credit_total;
        }
        // else no credit registered, keep GPAX at zero
        else {
            f_gpax = 0.0f;
        }
        return Math.min(f_gpax, maxGpax);
    }
}
